		clusterLabels: {"0": {"label": "AI, Science & The Future Of Work", "description": "Coarse grouping spanning generative AI in knowledge work, occupational skills, digital traces, and the science-of-science, from LLM-assisted writing and peer review to careers, patents, and scholarly recognition."}, "1": {"label": "Politics, Media & LLM Behavior", "description": "Broad grouping of political communication, online discourse, and social networks combined with LLM behavioral studies of persuasion, bias, belief dynamics, annotation, and ideology in news and social-media settings."}},
		clusterLayerLabels: [{"0": {"label": "Urban Mobility & Spatial Accessibility", "description": "Cities studied as data through human mobility, point-of-interest attribution, remote sensing, and spatial machine learning to quantify experienced segregation, accessibility gaps, crime risk, and migration flows."}, "1": {"label": "Social Network Structure & Hierarchy", "description": "Latent structure, community, and hierarchy in social and donor networks, using graph neural networks, aggregated relational data, and conformity models applied to friendship, illicit, and academic genealogy networks."}, "2": {"label": "Digital Traces & Online Behavior", "description": "Measuring digital behavior from web-tracking, mobile app, and infrastructure data, covering health-app effects, digital overuse recovery, ad-delivery skew, cloud dependence, and AI-generated content marketplaces."}, "3": {"label": "Generative AI, Work & Skills", "description": "How generative AI reshapes labor and knowledge work, mapping occupational skills, curricula, prompt recommender systems, creativity, and information diversity via digital-trace and benchmarking evidence."}, "4": {"label": "Science Of Science & Scholarly Careers", "description": "Bibliometric and career studies of scientists, examining LLM-assisted academic writing, peer review, interdisciplinarity, knowledge diffusion, ageing effects, and predictors of citation and recognition."}, "5": {"label": "LLMs For Text Annotation & Coding", "description": "Evaluating LLMs as content-analysis and annotation tools for CSS, addressing frame analysis, error decomposition, linguistically-responsible NLP, and the risk that LLM-based coding fabricates significance."}, "6": {"label": "LLMs As Survey & Preference Proxies", "description": "Using LLMs to simulate human respondents and measure alignment, covering demographic bias auditing in resume and targeted-text generation, purchase-intent elicitation, deep-value benchmarks, and open-ended survey quality."}, "7": {"label": "LLM Persuasion & Negotiation", "description": "Experiments on LLM agents in strategic dialogue, testing negotiation competitions, honest-versus-dishonest persuasion, belief manipulation, style matching, and cognitive-dissonance in moral decision making."}, "8": {"label": "Agent-Based & Reinforcement Learning Dynamics", "description": "Modeling collective human dynamics with LLM agents, reinforcement learning, and diffusion models, validating belief dynamics, spatial voting, behavioral archetypes, and learning under partial observability."}, "9": {"label": "Elections, News Diets & Populism", "description": "Political communication around 2024 elections, studying populist support, platform sorting and echo platforms, TikTok and X news exposure, radical-right media visibility, and politicized health-lifestyle discourse."}, "10": {"label": "Narrative, Framing & Deliberation", "description": "Computational discourse analysis of narrative, framing, and persuasion in online deliberation, covering counter-storytelling, media framing effects, affective polarization, multimodal fundraising, and narrative causal structure."}, "11": {"label": "Political Ideology In LLMs & Discourse", "description": "Ideology and strategic signaling in political text and language models, auditing LLM political bias, press-freedom underestimation, and summarization impact alongside NLP analysis of authoritarian and congressional discourse."}}, {"0": {"label": "Urban Mobility & Spatial Accessibility", "description": "Cities as data via human mobility, point-of-interest attribution, remote sensing, and spatial machine learning to study experienced segregation, accessibility, crime risk, and migration flows."}, "1": {"label": "Social Network Structure & Hierarchy", "description": "Latent structure, community, and hierarchy in social and donor networks using graph neural networks, aggregated relational data, and conformity models across friendship, illicit, and academic networks."}, "2": {"label": "Digital Traces & Online Behavior", "description": "Measuring digital behavior from web-tracking, mobile, and infrastructure data, spanning health-app effects, digital overuse recovery, ad-delivery skew, cloud dependence, and AI content marketplaces."}, "3": {"label": "Generative AI, Work & Skills", "description": "How generative AI reshapes labor and knowledge work through occupational-skill mapping, curricula, prompt recommenders, creativity, and information diversity via digital-trace and benchmarking evidence."}, "4": {"label": "Science Of Science & Scholarly Careers", "description": "Bibliometric and career studies examining LLM-assisted academic writing, peer review, interdisciplinarity, knowledge diffusion, ageing effects, and predictors of citation and recognition."}, "5": {"label": "LLM Agents: Simulation & Persuasion", "description": "Broader grouping of LLM-agent studies merging persuasion and negotiation with belief-dynamics simulation, spatial voting, reinforcement learning, and diffusion models of collective human behavior."}, "6": {"label": "LLMs As Survey & Preference Proxies", "description": "Using LLMs to simulate respondents and measure alignment, covering demographic bias auditing, purchase-intent elicitation, deep-value benchmarks, and open-ended survey response quality."}, "7": {"label": "Elections, News Diets & Populism", "description": "Political communication around 2024 elections, studying populist support, echo platforms, TikTok and X news exposure, radical-right media visibility, and politicized health-lifestyle discourse."}, "8": {"label": "Narrative, Framing & Deliberation", "description": "Computational discourse analysis of narrative and persuasion in online deliberation, covering counter-storytelling, media framing effects, affective polarization, multimodal fundraising, and narrative causal structure."}, "9": {"label": "Political Ideology In LLMs & Discourse", "description": "Ideology and strategic signaling in political text and language models, auditing LLM political bias and press-freedom underestimation alongside NLP analysis of authoritarian and congressional discourse."}}, {"0": {"label": "AI, Science & The Future Of Work", "description": "Coarse grouping spanning generative AI in knowledge work, occupational skills, digital traces, and the science-of-science, from LLM-assisted writing and peer review to careers, patents, and scholarly recognition."}, "1": {"label": "Politics, Media & LLM Behavior", "description": "Broad grouping of political communication, online discourse, and social networks combined with LLM behavioral studies of persuasion, bias, belief dynamics, annotation, and ideology in news and social-media settings."}}],
