		clusterLabels: {"0": {"label": "Urban mobility, accessibility & spatial risk", "description": "Broader grouping of city-scale computational work on accessibility, segregation, crime, eviction and disaster evacuation, drawing on mobility traces, point-of-interest attribution, remote sensing, and agent-based simulation."}, "1": {"label": "Science of science & scholarly writing", "description": "Broad science-of-science grouping spanning careers, patenting, interdisciplinarity, prizes and peer review alongside LLM-assisted academic writing, hallucinated citations, and off-channel diffusion of science through podcasts."}, "2": {"label": "Political discourse, media framing & polarization", "description": "Broad grouping of computational studies of news and social-media discourse, framing, polarization, media visibility, harassment and emotion, using NLP, network models, and LLM-based content extraction across major platforms."}, "3": {"label": "Generative AI in search & knowledge work", "description": "Broad grouping of audits and trace-data studies on how generative AI reshapes search, information diversity, creativity, administrative burden, and scientific and knowledge work, centered on ChatGPT and Google AI Overviews."}, "4": {"label": "LLM agents & collective behavior simulation", "description": "Broad grouping merging LLM-agent experiments on persuasion, manipulation, negotiation and alignment with formal and agent-based models of opinion dynamics, collective emotion, narrative diffusion, and multi-agent human simulation."}, "5": {"label": "LLMs as annotators, judges & survey proxies", "description": "Broad grouping of methodological work using LLMs for annotation, resume screening, translation, and survey-response simulation, surfacing demographic and political bias, ASR evaluation critiques, and researcher-driven result-hacking."}},
		clusterLayerLabels: [{"0": {"label": "Urban mobility, accessibility & spatial risk", "description": "City-scale studies of accessibility gaps, segregation, crime, eviction and evacuation using human mobility traces, point-of-interest attribution, satellite and thermal remote sensing, and agent-based simulation."}, "1": {"label": "Digital trace data: platforms & measurement", "description": "Studies measuring online behavior from digital traces, spanning cross-platform selective exposure, creator-economy audience networks, ad-delivery skew, and web/mobile tracking, with attention to participant churn, missing demographics, and LLM-based trace classification."}, "2": {"label": "Political discourse, media framing & polarization", "description": "Large-scale computational analysis of news and social-media discourse covering framing, affective polarization, media visibility, harassment, memes, and emotion, using NLP, graph attention networks, and LLM-based content extraction across platforms like Facebook, Reddit, TikTok and X."}, "3": {"label": "Science of science: careers & innovation", "description": "Bibliometric and network studies of scientific careers examining patenting, interdisciplinarity, ageing effects, advisor-advisee dynamics, subfield entry, and how peer review and prizes shape the diffusion and recognition of ideas."}, "4": {"label": "Generative AI in search & knowledge work", "description": "Audits and trace-data studies of how generative AI reshapes information seeking, search citations, creativity, administrative burden, and scientific and knowledge work, focused on ChatGPT and Google AI Overviews."}, "5": {"label": "LLMs in academic writing & peer review", "description": "Analyses of LLM adoption in scholarly publishing detected via excess-vocabulary and text signals, examining effects on writing speed, ESL scholars, data-sharing humility, and the risks of automating figure evaluation and peer review."}, "6": {"label": "Science, evidence & policy influence", "description": "Studies of how scientific knowledge and evidence circulate into policy and public debate, covering rulemaking comments, philanthropic agenda-setting, altmetric visibility, and epistemic appeals in contested science on Reddit, using large linked bibliometric datasets."}, "7": {"label": "LLMs as annotators, judges & survey proxies", "description": "Methodological work on using LLMs to label text, evaluate resumes, translate, and simulate survey responses, exposing demographic bias, political leaning, ASR epistemic injustice, and how configuration choices enable result-hacking."}, "8": {"label": "Opinion dynamics & collective behavior models", "description": "Formal and agent-based models of belief change, collective emotion, narrative contagion, community norm socialization, and collective causal learning, including tests of whether LLMs can emulate human belief dynamics."}, "9": {"label": "LLM agents: persuasion, negotiation & alignment", "description": "Experiments on LLM agents in negotiation, persuasion, manipulation, and group decision-making, probing honesty, deep-value generalization, cross-language homogenization, and human resistance to AI influence."}}, {"0": {"label": "Urban mobility, accessibility & spatial risk", "description": "Broader grouping of city-scale computational work on accessibility, segregation, crime, eviction and disaster evacuation, drawing on mobility traces, point-of-interest attribution, remote sensing, and agent-based simulation."}, "1": {"label": "Science of science & scholarly writing", "description": "Broad science-of-science grouping spanning careers, patenting, interdisciplinarity, prizes and peer review alongside LLM-assisted academic writing, hallucinated citations, and off-channel diffusion of science through podcasts."}, "2": {"label": "Political discourse, media framing & polarization", "description": "Broad grouping of computational studies of news and social-media discourse, framing, polarization, media visibility, harassment and emotion, using NLP, network models, and LLM-based content extraction across major platforms."}, "3": {"label": "Generative AI in search & knowledge work", "description": "Broad grouping of audits and trace-data studies on how generative AI reshapes search, information diversity, creativity, administrative burden, and scientific and knowledge work, centered on ChatGPT and Google AI Overviews."}, "4": {"label": "LLM agents & collective behavior simulation", "description": "Broad grouping merging LLM-agent experiments on persuasion, manipulation, negotiation and alignment with formal and agent-based models of opinion dynamics, collective emotion, narrative diffusion, and multi-agent human simulation."}, "5": {"label": "LLMs as annotators, judges & survey proxies", "description": "Broad grouping of methodological work using LLMs for annotation, resume screening, translation, and survey-response simulation, surfacing demographic and political bias, ASR evaluation critiques, and researcher-driven result-hacking."}}],
